def sync_once(source, target, state):
    since, seen = state.get("since"), set(state.get("seen", []))
    changes = source.changes(since)
    summary = {"upserted": 0, "deleted": 0, "skipped": 0}

    fresh = []
    for change in changes:
        if since is not None and change["updated_at"] == since and change["id"] in seen:
            summary["skipped"] += 1
        else:
            fresh.append(change)

    ordered = sorted(enumerate(fresh), key=lambda pair: (pair[1]["updated_at"], pair[0]))
    last = {}
    for index, change in ordered:
        last[change["id"]] = index
    for index, change in ordered:
        if last[change["id"]] != index:
            summary["skipped"] += 1
            continue
        if change.get("deleted"):
            if target.delete(change["id"]):
                summary["deleted"] += 1
        else:
            target.upsert(change["id"], change["data"])
            summary["upserted"] += 1

    if changes:
        top = max(change["updated_at"] for change in changes)
        if since is None or top > since:
            since, seen = top, set()
        seen |= {change["id"] for change in changes if change["updated_at"] == since}
        state["since"] = since
        state["seen"] = sorted(seen)
    return summary

