class Source:
    def __init__(self):
        self.log = []
        self.asked = []
    def add(self, id, t, deleted=False, **data):
        change = {"id": id, "updated_at": t, "data": data}
        if deleted:
            change["deleted"] = True
        self.log.append(change)
    def changes(self, since):
        self.asked.append(since)
        return [c for c in self.log if since is None or c["updated_at"] >= since]

class Target:
    def __init__(self):
        self.rows = {}
        self.writes = 0
    def upsert(self, id, data):
        self.writes += 1
        self.rows[id] = dict(data)
    def delete(self, id):
        return self.rows.pop(id, None) is not None

def fresh_state():
    return {"since": None, "seen": []}

@test("a first run copies everything")
def _():
    src, tgt, state = Source(), Target(), fresh_state()
    src.add("a", 1, name="A")
    src.add("b", 2, name="B")
    check_eq(sync_once(src, tgt, state), {"upserted": 2, "deleted": 0, "skipped": 0})
    check_eq(tgt.rows, {"a": {"name": "A"}, "b": {"name": "B"}})
    check_eq(state, {"since": 2, "seen": ["b"]})

@test("a second run only sees what is new")
def _():
    src, tgt, state = Source(), Target(), fresh_state()
    src.add("a", 1, name="A")
    src.add("b", 2, name="B")
    sync_once(src, tgt, state)
    check_eq(sync_once(src, tgt, state), {"upserted": 0, "deleted": 0, "skipped": 1})
    src.add("c", 2, name="C")
    src.add("a", 3, name="A2")
    check_eq(sync_once(src, tgt, state), {"upserted": 2, "deleted": 0, "skipped": 1})
    check_eq(tgt.rows["a"], {"name": "A2"})
    check_eq(state, {"since": 3, "seen": ["a"]})
    check_eq(src.asked, [None, 2, 2])

@test("several changes to one record")
def _():
    src, tgt, state = Source(), Target(), fresh_state()
    src.add("a", 5, name="later")
    src.add("a", 4, name="earlier")
    src.add("b", 5, name="b1")
    src.add("b", 5, name="b2")
    check_eq(sync_once(src, tgt, state), {"upserted": 2, "deleted": 0, "skipped": 2})
    check_eq(tgt.rows, {"a": {"name": "later"}, "b": {"name": "b2"}})
    check_eq(tgt.writes, 2)

@test("deletes")
def _():
    src, tgt, state = Source(), Target(), fresh_state()
    src.add("a", 1, name="A")
    sync_once(src, tgt, state)
    src.add("a", 2, deleted=True)
    src.add("ghost", 2, deleted=True)
    check_eq(sync_once(src, tgt, state), {"upserted": 0, "deleted": 1, "skipped": 1})
    check_eq(tgt.rows, {})
    check_eq(state, {"since": 2, "seen": ["a", "ghost"]})

@test("nothing to do")
def _():
    src, tgt, state = Source(), Target(), fresh_state()
    check_eq(sync_once(src, tgt, state), {"upserted": 0, "deleted": 0, "skipped": 0})
    check_eq(state, {"since": None, "seen": []})

